import {mountRain} from './rain.mjs';
import {mountChallenge} from './challenge.mjs';
let stopGame=null;
const app=document.querySelector('#app');let sound=false,ctx,total=0,settings={limit:20,op:'mix'};
try{total=Number(localStorage.getItem('toan-stars'))||0}catch{}updateStars();
const modes=[{id:'rain',icon:'🌦️',title:'Mưa phép tính',desc:'Tính nhẩm, hứng điểm! Đừng để phép tính chạm đáy.',tag:'MỚI · TÍNH NHẨM NHANH',color:'teal',label:'Đón cơn mưa'},{id:'practice',icon:'🌱',title:'Vườn luyện tập',desc:'Từng bước nhỏ, tự tin lớn. Có gợi ý giúp bé!',tag:'THOẢI MÁI HỌC',color:'green',label:'Luyện tập'},{id:'bubble',icon:'🫧',title:'Bắt bong bóng',desc:'Tìm đáp án đúng, chạm và… bụp!',tag:'NHANH TAY · TINH MẮT',color:'blue',label:'Chơi ngay'},{id:'memory',icon:'🧩',title:'Lật thẻ thần kỳ',desc:'Ghép phép tính với đáp án. Thử tài trí nhớ!',tag:'GHI NHỚ · KHÁM PHÁ',color:'orange',label:'Lật thẻ'},{id:'mystery',icon:'🔎',title:'Số nào trốn mất?',desc:'Làm thám tử, tìm con số còn thiếu.',tag:'SUY LUẬN · TÌM TÒI',color:'pink',label:'Khám phá'}];
function updateStars(){document.querySelector('#stars').textContent='⭐ '+total}
function award(){total++;updateStars();try{localStorage.setItem('toan-stars',total)}catch{}}
function beep(win=true){if(!sound)return;try{ctx??=new(window.AudioContext||window.webkitAudioContext)();ctx.resume();[0,.12,.24].forEach((t,i)=>{let o=ctx.createOscillator(),g=ctx.createGain();o.connect(g);g.connect(ctx.destination);o.type='sine';o.frequency.value=(win?520:220)*(1+i*.25);g.gain.setValueAtTime(.08,ctx.currentTime+t);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+t+.2);o.start(ctx.currentTime+t);o.stop(ctx.currentTime+t+.2)})}catch{}}
document.querySelector('#sound').onclick=()=>{sound=!sound;document.querySelector('#sound').textContent=sound?'🔊':'🔇';document.querySelector('#sound').setAttribute('aria-label',sound?'Tắt âm thanh':'Bật âm thanh');if(sound)beep()};
document.querySelector('#brand').onclick=e=>{e.preventDefault();home()};
function home(){stopGame?.();stopGame=null;app.innerHTML=`<section class="welcome"><div><div class="eyebrow">XIN CHÀO, NHÀ THÁM HIỂM NHÍ!</div><h1>Hôm nay mình<br>chơi <span>toán</span> nhé<span class="spark">✦</span></h1><p>Chọn một trò chơi. Bắt đầu chuyến phiêu lưu!</p></div><div class="welcome-sticker" aria-hidden="true"><span>🌈</span><b>1 + 2 = <em>3</em></b><small>Thêm một chút giỏi mỗi ngày</small></div></section><section class="settings" aria-label="Chọn bài học"><span class="settings-title">🎯 Bé muốn học</span><div class="segments" id="op">${[['mix','Cộng & trừ'],['plus','Phép cộng'],['minus','Phép trừ']].map(([v,t])=>`<button data-value="${v}" class="${settings.op===v?'active':''}" aria-pressed="${settings.op===v}">${t}</button>`).join('')}</div><label>Phạm vi <select id="limit"><option value="10" ${settings.limit===10?'selected':''}>Đến 10</option><option value="20" ${settings.limit===20?'selected':''}>Đến 20</option></select></label></section><div class="section-head"><h2>Cả một đảo niềm vui</h2><span>5 cách chơi · Bé chọn nhé!</span></div><section class="cards">${modes.map((m,i)=>`<button class="game-card ${m.color} ${i===0?'featured':''}" data-mode="${m.id}"><div class="card-top"><span class="game-icon">${m.icon}</span><span class="card-num">0${i+1}</span></div><span class="tag">${m.tag}</span><h3>${m.title}</h3><p>${m.desc}</p><span class="card-cta">${m.label} <span>↗</span></span></button>`).join('')}<aside class="tip"><span>✨</span><h3>Mỗi lần thử là<br>một lần tiến bộ.</h3><p>Chơi một lượt nhỏ,<br>học thêm một điều hay.</p><div>+ &nbsp; − &nbsp; = &nbsp; ♡</div></aside></section>`;app.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>start(b.dataset.mode));app.querySelectorAll('#op button').forEach(b=>b.onclick=()=>{settings.op=b.dataset.value;home()});app.querySelector('#limit').onchange=e=>settings.limit=+e.target.value}
function start(id){stopGame?.();stopGame=null;const selectedMode=modes.find(m=>m.id===id);stopGame=id==='rain'?mountRain(app,{settings,home,award,beep}):mountChallenge(app,{mode:selectedMode,settings,home,award,beep});}
home();
